// DNS wire encoding and transport only. No guest ALU or DNS answer cache.
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <sys/socket.h>
#include <cerrno>
#include <cstring>
#include <stdexcept>
#include <string>
#include <vector>
using std::string;
static void u16(string& s,unsigned n){s.push_back(n>>8);s.push_back(n);}
static unsigned r16(const string& s,size_t p){if(p+2>s.size())throw std::runtime_error("Truncated DNS message");return ((unsigned char)s[p]<<8)|(unsigned char)s[p+1];}
static string pystr(PyObject* o){const char* s=PyUnicode_AsUTF8(o);if(!s)throw std::runtime_error("Expected DNS text");return s;}
static void name(string& s,const string& text){size_t p=0;while(p<text.size()){size_t e=text.find('.',p);if(e==string::npos)e=text.size();size_t n=e-p;if(n>63)throw std::runtime_error("DNS label too long");s.push_back(n);s.append(text,p,n);p=e+1;}s.push_back(0);}
static string txt(const string& s){string out;for(size_t p=0;p<s.size();p+=200){size_t n=std::min(size_t(200),s.size()-p);out.push_back(n);out.append(s,p,n);}if(s.empty())out.push_back(0);return out;}
static void rr(string& w,const string& owner,unsigned cls,const string& data){name(w,owner+".rv.test.");u16(w,16);u16(w,cls);w.append(4,'\0');u16(w,data.size());w+=data;}
static PyObject* query(PyObject*,PyObject* args){unsigned id;const char* owner;if(!PyArg_ParseTuple(args,"Is",&id,&owner))return nullptr;try{string w;u16(w,id);u16(w,0);u16(w,1);w.append(6,'\0');name(w,string(owner)+".rv.test.");u16(w,16);u16(w,1);return PyBytes_FromStringAndSize(w.data(),w.size());}catch(const std::exception& e){PyErr_SetString(PyExc_ValueError,e.what());return nullptr;}}
static PyObject* update(PyObject*,PyObject* args){unsigned id;PyObject *changes,*previous;const char* prerequisite;if(!PyArg_ParseTuple(args,"IOOs",&id,&changes,&previous,&prerequisite))return nullptr;try{Py_ssize_t n=PySequence_Size(changes);if(n<0||n>1000)throw std::runtime_error("Invalid update size");string w;u16(w,id);u16(w,0x2800);u16(w,1);u16(w,previous==Py_None?0:1);u16(w,n*2);u16(w,0);name(w,"rv.test.");u16(w,6);u16(w,1);if(previous!=Py_None)rr(w,prerequisite,1,txt(pystr(previous)));for(Py_ssize_t i=0;i<n;i++){PyObject* pair=PySequence_GetItem(changes,i);if(!pair)throw std::runtime_error("Invalid update");PyObject* a=PySequence_GetItem(pair,0);PyObject* b=PySequence_GetItem(pair,1);if(!a||!b){Py_XDECREF(a);Py_XDECREF(b);Py_DECREF(pair);throw std::runtime_error("Invalid update pair");}string owner=pystr(a),value=pystr(b);Py_DECREF(a);Py_DECREF(b);Py_DECREF(pair);rr(w,owner,255,"");rr(w,owner,1,txt(value));}return PyBytes_FromStringAndSize(w.data(),w.size());}catch(const std::exception& e){PyErr_SetString(PyExc_ValueError,e.what());return nullptr;}}
static void sendall(int fd,const string& s){size_t p=0;while(p<s.size()){ssize_t n=send(fd,s.data()+p,s.size()-p,MSG_NOSIGNAL);if(n<0&&errno==EINTR)continue;if(n<=0)throw std::runtime_error(string("DNS send: ")+strerror(errno));p+=n;}}
static PyObject* exchange(PyObject*,PyObject* args){int fd;PyObject* requests;if(!PyArg_ParseTuple(args,"iO",&fd,&requests))return nullptr;try{Py_ssize_t n=PySequence_Size(requests);if(n<1||n>64)throw std::runtime_error("Batch must contain 1..64 requests");string packet;for(Py_ssize_t i=0;i<n;i++){PyObject* item=PySequence_GetItem(requests,i);char* data;Py_ssize_t len;if(!item||PyBytes_AsStringAndSize(item,&data,&len)<0){Py_XDECREF(item);throw std::runtime_error("Expected DNS bytes");}if(len>65535){Py_DECREF(item);throw std::runtime_error("DNS packet too large");}u16(packet,len);packet.append(data,len);Py_DECREF(item);}sendall(fd,packet);std::vector<string> replies;string incoming;size_t cursor=0;auto need=[&](size_t count){while(incoming.size()-cursor<count){char buffer[65536];ssize_t got=recv(fd,buffer,sizeof(buffer),0);if(got<0&&errno==EINTR)continue;if(got<=0)throw std::runtime_error(got==0?"DNS connection closed":string("DNS recv: ")+strerror(errno));incoming.append(buffer,got);}};for(Py_ssize_t i=0;i<n;i++){need(2);unsigned size=r16(incoming,cursor);cursor+=2;need(size);replies.push_back(incoming.substr(cursor,size));cursor+=size;}if(cursor!=incoming.size())throw std::runtime_error("Unsolicited DNS response bytes");PyObject* out=PyList_New(n);for(Py_ssize_t i=0;i<n;i++)PyList_SET_ITEM(out,i,PyBytes_FromStringAndSize(replies[i].data(),replies[i].size()));return out;}catch(const std::exception& e){PyErr_SetString(PyExc_RuntimeError,e.what());return nullptr;}}
static size_t skip(const string& s,size_t p){while(true){if(p>=s.size())throw std::runtime_error("Truncated name");unsigned n=(unsigned char)s[p++];if(!n)return p;if((n&0xc0)==0xc0){if(p>=s.size())throw std::runtime_error("Truncated pointer");return p+1;}if(n&0xc0||p+n>s.size())throw std::runtime_error("Malformed name");p+=n;}}
static PyObject* parse(PyObject*,PyObject* arg){char* bytes;Py_ssize_t len;if(PyBytes_AsStringAndSize(arg,&bytes,&len)<0)return nullptr;try{string s(bytes,len);if(!(r16(s,2)&0x400)||r16(s,4)!=1)throw std::runtime_error("Expected authoritative answer");unsigned answers=r16(s,6),found=0;size_t p=skip(s,12)+4;string result;for(unsigned i=0;i<answers;i++){p=skip(s,p);unsigned type=r16(s,p),size=r16(s,p+8);p+=10;size_t end=p+size;if(end>s.size())throw std::runtime_error("Truncated RR");if(type==16){found++;while(p<end){unsigned n=(unsigned char)s[p++];if(p+n>end)throw std::runtime_error("Truncated TXT");result.append(s,p,n);p+=n;}}p=end;}if(found!=1)throw std::runtime_error("Expected exactly one TXT record");return PyUnicode_DecodeASCII(result.data(),result.size(),"strict");}catch(const std::exception& e){PyErr_SetString(PyExc_ValueError,e.what());return nullptr;}}
static PyMethodDef methods[]={{"query",query,METH_VARARGS,"Encode QUERY"},{"update",update,METH_VARARGS,"Encode UPDATE"},{"exchange",exchange,METH_VARARGS,"Exchange a bounded DNS batch"},{"parse_txt",parse,METH_O,"Decode TXT"},{nullptr,nullptr,0,nullptr}};
static PyModuleDef mod={PyModuleDef_HEAD_INIT,"_fastwire",nullptr,-1,methods};
PyMODINIT_FUNC PyInit__fastwire(){return PyModule_Create(&mod);}
